def verify_scales_from_atlas():
 """Recalcula somente cenários descritivos; não estima ou modifica modelos."""
 import dlm_revisao as r
 panel=pd.read_parquet(ROOT/'data/processed/df_tcc_2013_2024.parquet').sort_values(['uf','data_base']).reset_index(drop=True)
 panel['data_base']=pd.to_datetime(panel.data_base)
 raw=ROOT/'data/raw/atlas_desastres/atlas.csv'
 assert hashlib.sha256(raw.read_bytes()).hexdigest()=='6ca29008a60a30e9f45d0f451da7750f850d8902704487798e1ef39ca3da44af','Atlas não corresponde ao checkpoint íntegro'
 a=pd.read_csv(raw,sep=';',encoding='latin1',low_memory=False)
 a['date']=pd.to_datetime(a.Data_Evento,format='%d/%m/%Y',errors='coerce')
 a=a[a.date.dt.year.between(2013,2024)].copy();assert len(a)==40339
 a['data_base']=a.date.dt.to_period('M').dt.to_timestamp();a['uf']=a.Sigla_UF.str.strip();a['classe_analitica']=a.Cod_Cobrade.map(r.analytical)
 index=pd.MultiIndex.from_frame(panel[['uf','data_base']]);sc=[]
 for col,mask in r.masks(a,panel).items():
  numerator=a.loc[mask].groupby(['uf','data_base']).Cod_IBGE_Mun.nunique().reindex(index,fill_value=0).to_numpy()
  coverage=numerator/panel.uf.map(r.MUNICIPIOS).to_numpy()
  for period,end in [('Total','2024-12-01'),('Pré','2020-01-01')]:
   x=coverage[panel.data_base<=end];positive=x[x>0]
   sc.append(dict(periodo=period,coluna=col,positivo_mediana=float(np.median(positive)) if len(positive) else np.nan,positivo_p90=float(np.quantile(positive,.9)) if len(positive) else np.nan,maximo=float(np.max(x)),positivos=int(len(positive))))
 actual=pd.DataFrame(sc).sort_values(['periodo','coluna']).reset_index(drop=True)
 saved=pd.read_csv(ROOT/'outputs/tables'/SOURCES['scale']).sort_values(['periodo','coluna']).reset_index(drop=True)
 assert actual[['periodo','coluna']].equals(saved[['periodo','coluna']])
 assert np.allclose(actual.select_dtypes('number'),saved.select_dtypes('number'),atol=1e-15,rtol=1e-12,equal_nan=True),'Cenários divergem do Atlas'
 return {'status':'aprovado','cenarios':len(sc),'registros_atlas':len(a)}

def load():
 d={};manifest={}
 for key,rel in SOURCES.items():
  p=ROOT/'outputs/tables'/rel;df=pd.read_csv(p)
  d[key]=json.loads(df.to_json(orient='records',force_ascii=False));manifest[rel]=dict(rows=len(df),sha256=hashlib.sha256(p.read_bytes()).hexdigest())
 assert len(d['gm'])==42 and len(d['m'])==552 and len(d['b'])==92
 assert len([r for r in d['g'] if r['Família']=='PRINCIPAL'])==42
 assert sum(r['p BH'] is not None and r['p BH']<.05 for r in d['gm'])==10
 main=[r for r in d['cr'] if r['especificacao']=='Principal' and r['endpoint']=='acumulado']
 assert len(main)==46 and not any(r['q'] is not None and r['q']<.05 for r in main)
 s=pd.read_csv(ROOT/'outputs/tables/segunda_etapa/series_nacionais_agregadas.csv')
 d['series']=json.loads(s.to_json(orient='records',force_ascii=False))
 manifest['segunda_etapa/series_nacionais_agregadas.csv']={'rows':len(s),'sha256':hashlib.sha256((ROOT/'outputs/tables/segunda_etapa/series_nacionais_agregadas.csv').read_bytes()).hexdigest()}
 d['manifest']=manifest
 return d

